1	import type { Config } from "../config.js";
2	import type { StorageProvider as StorageProviderImpl } from "./types.js";
3	import type { StorageProvider as StorageProviderId } from "@paperclipai/shared";
4	import { createLocalDiskStorageProvider } from "./local-disk-provider.js";
5	import { createS3StorageProvider } from "./s3-provider.js";
6	
7	type StorageProviderFactory = (config: Config) => StorageProviderImpl;
8	const externalProviders = new Map<StorageProviderId, StorageProviderFactory>();
9	
10	export function registerStorageProvider(id: StorageProviderId, factory: StorageProviderFactory): void {
11	  externalProviders.set(id, factory);
12	}
13	
14	export function createStorageProviderFromConfig(config: Config): StorageProviderImpl {
15	  if (config.storageProvider === "local_disk") {
16	    return createLocalDiskStorageProvider(config.storageLocalDiskBaseDir);
17	  }
18	
19	  if (config.storageProvider === "s3") {
20	    return createS3StorageProvider({
21	      bucket: config.storageS3Bucket,
22	      region: config.storageS3Region,
23	      endpoint: config.storageS3Endpoint,
24	      prefix: config.storageS3Prefix,
25	      forcePathStyle: config.storageS3ForcePathStyle,
26	    });
27	  }
28	
29	  const external = externalProviders.get(config.storageProvider);
30	  if (external) {
31	    return external(config);
32	  }
33	
34	  throw new Error(`Unknown storage provider: ${config.storageProvider}`);
35	}
